import cv2,numpy as np,math
from PIL import Image
im=np.array(Image.open('/app/target.png')).astype(np.float32)
cols=np.array([[242,223,169],[202,212,176],[156,188,172],[129,158,155],[128,147,99],[97,124,134],[65,89,108],[57,91,68],[98,62,56],[35,58,88],[248,244,236]],np.float32)
lab=np.sqrt(((im[:,:,None,:]-cols[None,None,:,:])**2).sum(3)).argmin(2).astype(np.uint8);lab=cv2.medianBlur(lab,3)
for stride in [2,3,4]:
 nseg=0;linel=0;conl=0;comps=0;maxconnect=0
 for k in range(10):
  maskclass=(lab==k).astype(np.uint8);dt=cv2.distanceTransform(maskclass,cv2.DIST_L2,5)
  n,cc,st,cen=cv2.connectedComponentsWithStats(maskclass,8)
  for cid,area in enumerate(st[1:,4],1):
   if area<25:continue
   comps+=1;x0,y0,w,h=st[cid,:4]
   current=None
   for y in range(y0+stride//2,y0+h,stride):
    row=(cc[y,x0:x0+w]==cid)&(dt[y,x0:x0+w]>=2.5)
    a=np.flatnonzero(row&~np.r_[False,row[:-1]])
    b=np.flatnonzero(row&~np.r_[row[1:],False])
    for aa,bb in zip(a,b):
     aa+=x0;bb+=x0
     nseg+=1;linel+=bb-aa
     if current is None:
      # choose starting left endpoint
      current=(y,aa)
     else:
      d1=math.hypot(y-current[0],aa-current[1]);d2=math.hypot(y-current[0],bb-current[1])
      if d1<=d2:target=(y,aa);other=(y,bb)
      else:target=(y,bb);other=(y,aa)
      dc=math.hypot(target[0]-current[0],target[1]-current[1]);conl+=dc;maxconnect=max(maxconnect,dc)
      current=other
 print('stride',stride,'comp',comps,'segments',nseg,'line_px',linel,'conn_px',round(conl),'pathpx',round(linel+conl),'pathmm',round((linel+conl)*.222),'max connector',round(maxconnect),'samples8px',round((linel+conl)/8),'turn overhead',nseg*2)
